def push_fruit(FruitStack, Fruit):
    if Fruit['Price'] < 100:
        FruitStack.append(Fruit)

def pop_fruit(FruitStack):
    if len(FruitStack) == 0:
        print("UNDERFLOW")
    else:
        return FruitStack.pop()

def display(FruitStack):
    if len(FruitStack) == 0:
        print("EMPTY STACK")
    else:
        for i in range(len(FruitStack)-1, -1, -1):
            print(FruitStack[i])

