(a) def Find_Pattern():
    f = open("LOGS.TXT", "r")
    for line in f:
        if line.startswith("ERROR"):
            print(line, end='')
    f.close()

(b) def ContainsChar():
    f = open("DOCUMENT.TXT", "r")
    for word in f.read().split():
        if 'o' in word.lower():
            print(word)
    f.close()

def PushHighPerformers():
    for emp_id, score in EMPLOYEE_PERFORMANCE.items():
        if score >= 90:
            TOP_PERFORMERS_LIST.append(emp_id)

def IsPerformanceListEmpty():
    return len(TOP_PERFORMERS_LIST) == 0

def PopPerformer():
    if IsPerformanceListEmpty():
        print("Stack Underflow: No top performer to pop.")
    else:
        return TOP_PERFORMERS_LIST.pop()

