(a)(I) SELECT PName, Price FROM PRODUCTS WHERE Category='Electronics' AND Price>100.00;
(a)(II) SELECT Category, COUNT(*) FROM PRODUCTS GROUP BY Category;
(a)(III) SELECT * FROM PRODUCTS ORDER BY LastUpdated ASC;
(a)(IV) UPDATE PRODUCTS SET Price=0 WHERE Quantity IS NULL;
(b)(I) SELECT Avg(Quantity) FROM PRODUCTS WHERE Category='Peripherals'; -> average of 200,150,NULL(excluded),... = (200+150+NULL-excluded)/count of non-null rows
(b)(II) SELECT DISTINCT Category -> Electronics, Peripherals, Accessories, Storage, Audio, Home
(b)(III) SELECT COUNT(PID) WHERE Quantity<100 -> counts rows with Quantity<100 (NULL excluded by default)
(b)(IV) SELECT PName,Category WHERE PName LIKE '%Speaker%' -> ('Smart Speaker','Electronics')
(b) VERIFIED against the actual 10-row table: (I) AVG Quantity for Peripherals = 175.0  (II) DISTINCT Category = Electronics, Peripherals, Accessories, Storage, Audio, Home  (III) COUNT(PID) WHERE Quantity<100 = 2  (IV) PName,Category WHERE LIKE '%Speaker%' = ('Smart Speaker','Electronics')

import csv
def RecentOrders():
    with open("ORDERS.CSV", "r", newline="") as f:
        reader = csv.reader(f)
        for row in reader:
            if row[2].startswith("2024"):
                print(row[0], row[3])

def AddOrder(newOrder):
    with open("ORDERS.CSV", "a", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(newOrder)

